#[derive(Clone, Debug, Default, PartialEq)]
pub struct GateSelectorConfig {
    pub enabled: bool,
    pub dry_run: bool,
    pub evaluation_interval_sec: i64,
    pub interfaces: Vec<GateIfaceConfig>,
    /// резервные шлюзы — из конструктора путей обхода (backups)
    pub from_alternatives: bool,
    /// устройства резервных шлюзов по приоритету (после основного)
    pub backups: Vec<String>,
    pub probes: GateProbesConfig,
    pub thresholds: GateThresholdsConfig,
    pub switching: GateSwitchingConfig,
    pub repair: GateRepairConfig,
}

impl GateSelectorConfig {
    /// Слой YAML/JSON поверх текущих значений (незнакомые ключи — как yaml.v3: пропуск).
    pub fn apply(&mut self, v: &Value, p: &str) -> Result<(), String> {
        let m = match v {
            Value::Map(m) => m,
            Value::Null => return Ok(()),
            _ => return Err(format!("{}: ожидается словарь", if p.is_empty() { "конфиг" } else { p })),
        };
        for (k, x) in m {
            let q = join(p, k);
            match k.as_str() {
                "enabled" => self.enabled = dec_bool(x, &q)?,
                "dry_run" => self.dry_run = dec_bool(x, &q)?,
                "evaluation_interval_sec" => self.evaluation_interval_sec = dec_int(x, &q)?,
                "interfaces" => self.interfaces = match x { Value::List(l) => { let mut o = Vec::with_capacity(l.len()); for (i, it) in l.iter().enumerate() { let mut t = GateIfaceConfig::default(); t.apply(it, &format!("{}[{}]", q, i))?; o.push(t); } o } Value::Null => Vec::new(), _ => return Err(format!("{}: ожидается список", q)) },
                "from_alternatives" => self.from_alternatives = dec_bool(x, &q)?,
                "backups" => self.backups = dec_str_list(x, &q)?,
                "probes" => self.probes.apply(x, &q)?,
                "thresholds" => self.thresholds.apply(x, &q)?,
                "switching" => self.switching.apply(x, &q)?,
                "repair" => self.repair.apply(x, &q)?,
                _ => {}
            }
        }
        Ok(())
    }

    /// Все поля по путям «секция.ключ» (как cfgWalk в Go).
    pub fn walk<'a>(&'a self, p: &str, f: &mut dyn FnMut(&str, Field<'a>)) {
        f(&join(p, "enabled"), Field::Bool(&self.enabled));
        f(&join(p, "dry_run"), Field::Bool(&self.dry_run));
        f(&join(p, "evaluation_interval_sec"), Field::Int(&self.evaluation_interval_sec));
        f(&join(p, "interfaces"), Field::Complex);
        f(&join(p, "from_alternatives"), Field::Bool(&self.from_alternatives));
        f(&join(p, "backups"), Field::StrList(&self.backups));
        self.probes.walk(&join(p, "probes"), f);
        self.thresholds.walk(&join(p, "thresholds"), f);
        self.switching.walk(&join(p, "switching"), f);
        self.repair.walk(&join(p, "repair"), f);
    }

    /// Поле на запись по пути относительно этой структуры.
    pub fn field_mut(&mut self, path: &str) -> Option<FieldMut<'_>> {
        let (head, rest) = match path.split_once('.') { Some((h, r)) => (h, Some(r)), None => (path, None) };
        match (head, rest) {
            ("enabled", None) => Some(FieldMut::Bool(&mut self.enabled)),
            ("dry_run", None) => Some(FieldMut::Bool(&mut self.dry_run)),
            ("evaluation_interval_sec", None) => Some(FieldMut::Int(&mut self.evaluation_interval_sec)),
            ("from_alternatives", None) => Some(FieldMut::Bool(&mut self.from_alternatives)),
            ("backups", None) => Some(FieldMut::StrList(&mut self.backups)),
            ("probes", Some(r)) => self.probes.field_mut(r),
            ("thresholds", Some(r)) => self.thresholds.field_mut(r),
            ("switching", Some(r)) => self.switching.field_mut(r),
            ("repair", Some(r)) => self.repair.field_mut(r),
            _ => None,
        }
    }
}

