#[derive(Clone, Debug, Default, PartialEq)]
pub struct DNSGuardConfig {
    /// off | observe | active | targeted
    pub mode: String,
    /// auto | smartdns | dnsmasq
    pub backend: String,
    /// IPv6 плохой столько — запрет AAAA
    pub v6_enter_sec: i64,
    /// IPv4 сломан столько — DNS64
    pub v4_enter_sec: i64,
    /// всё в норме столько — как было
    pub recover_sec: i64,
    /// на время сбоя IPv4
    pub dns64_servers: Vec<String>,
    /// smartdns: файл вышестоящих серверов
    pub upstream_file: String,
    /// smartdns: файл запрета AAAA
    pub guard_file: String,
    /// smartdns: кэш на диске (сбрасывается)
    pub cache_file: String,
    /// снимок обычных настроек и аварийного режима
    pub state_file: String,
    /// в no_aaaa ещё и RA без шлюза (ra_lifetime=0)
    pub withdraw_ra: bool,
    /// targeted, smartdns: запреты AAAA/A доменов сетей
    pub targets_file: String,
    /// targeted: первый штраф, мин (дальше вдвое дольше)
    pub target_base_min: i64,
    /// targeted: самый долгий штраф, ч
    pub target_max_hours: i64,
    /// targeted: куда уводить плохую сеть по порядку: proto (другой протокол через DNS), устройства (dgroute.go)
    pub alternatives: Vec<String>,
    /// targeted: лимитированные пути (устройства)
    pub metered: Vec<String>,
    /// targeted: суточный лимит лимитированного пути, МБ
    pub metered_day_mb: i64,
    /// targeted: сайты «мой IP» — проверка из браузера, откуда смотрит интернет
    pub check_domains: Vec<String>,
    /// через что их пускать: "" — первый рабочий путь обхода, direct — напрямую, proto — только IPv6 (без A), устройство
    pub check_via: String,
    /// ретрансляторы «имя@адрес» (узел ZeroTier/LAN): путь обхода @имя через этот узел
    pub relays: Vec<String>,
    /// ограничение скорости пути через ретранслятор в каждую сторону, Мбит/с (0 — нет)
    pub relay_mbit: i64,
    /// targeted: сетям со штрафом за IPv6 — отказ в новых IPv6-соединениях (dgv6.go)
    pub reject_v6: bool,
    /// пробы IPv6 ниже, % — отказ всем IPv6-соединениям в интернет (0 — никогда)
    pub reject_all_v6_score: i64,
    /// ...дольше, с
    pub reject_all_v6_sec: i64,
}

